html:
{%- set received = doc.cheque_type == "Received" -%}
<div class="cheque-receipt">
	<style>
		.cheque-receipt { font-size: 13px; color: #1f272e; }
		.cheque-receipt h2 { font-size: 20px; margin: 0 0 4px; }
		.cheque-receipt .muted { color: #6b7280; }
		.cheque-receipt table { width: 100%; border-collapse: collapse; margin-top: 16px; }
		.cheque-receipt th, .cheque-receipt td { padding: 6px 8px; border-bottom: 1px solid #e5e7eb; text-align: left; }
		.cheque-receipt .num { text-align: right; }
		.cheque-receipt .box { border: 1px solid #e5e7eb; border-radius: 8px; padding: 12px 16px; margin-top: 16px; }
		.cheque-receipt .sign { margin-top: 56px; display: flex; justify-content: space-between; }
		.cheque-receipt .sign div { border-top: 1px solid #9ca3af; padding-top: 4px; width: 40%; }
	</style>

	<h2>{{ _("Cheque Acknowledgement") if received else _("Cheque Issue Voucher") }}</h2>
	<div class="muted">{{ doc.company }} &middot; {{ doc.name }} &middot; {{ doc.get_formatted("posting_date") }}</div>

	<div class="box">
		{% if received %}
		{{ _("Received from") }} <b>{{ doc.party_name or doc.party }}</b>
		{% else %}
		{{ _("Issued to") }} <b>{{ doc.party_name or doc.party }}</b>
		{% endif %}
		{{ _("cheque no.") }} <b>{{ doc.cheque_no }}</b> {{ _("dated") }} <b>{{ doc.get_formatted("cheque_date") }}</b>
		{% if doc.bank_name %}{{ _("drawn on") }} <b>{{ doc.bank_name }}{% if doc.bank_branch %}, {{ doc.bank_branch }}{% endif %}</b>{% endif %}
		{{ _("for") }} <b>{{ doc.get_formatted("amount") }}</b>
		<div class="muted">({{ frappe.utils.money_in_words(doc.amount, doc.party_account_currency) }})</div>
	</div>

	{% if doc.references %}
	<table>
		<thead>
			<tr>
				<th>{{ _("Invoice") }}</th>
				<th>{{ _("Date") }}</th>
				<th class="num">{{ _("Allocated") }}</th>
			</tr>
		</thead>
		<tbody>
			{% for row in doc.references %}
			<tr>
				<td>{{ row.reference_name }}</td>
				<td>{{ row.get_formatted("posting_date") }}</td>
				<td class="num">{{ row.get_formatted("allocated_amount", doc) }}</td>
			</tr>
			{% endfor %}
			{% if doc.unallocated_amount %}
			<tr>
				<td colspan="2">{{ _("On account") }}</td>
				<td class="num">{{ doc.get_formatted("unallocated_amount") }}</td>
			</tr>
			{% endif %}
		</tbody>
	</table>
	{% endif %}

	{% if received %}
	<p class="muted" style="margin-top: 16px;">
		{{ _("This acknowledges receipt of the cheque only. Payment is subject to realisation.") }}
	</p>
	{% endif %}

	<div class="sign">
		<div>{{ _("Received by") if received else _("Issued by") }}</div>
		<div>{{ _("Party signature") }}</div>
	</div>
</div>
